"""MDP(Markov Decision Process) 정의 파일.

강화학습 문제는 (S, A, R, P, γ) 로 정의되는데, 이 파일이 그중
  S: 관측(상태)을 어떻게 구성할지  → OBSERVATION
  A: 행동을 무엇으로 할지          → SPEED_DELTAS
  R: 보상을 어떻게 줄지            → REWARD
  에피소드 길이/시간 해상도        → SIMULATION
를 결정한다. (전이확률 P는 SUMO 시뮬레이터 자체, γ는 train_config.py의 gamma)

이 파일만 수정하면 sumo_env.py를 건드리지 않고 MDP를 바꿀 수 있다.
"""

# ──────────────────────────────────────────────────────────────
# 1) 시뮬레이션 시간 설정
# ──────────────────────────────────────────────────────────────
SIMULATION = {
    "step_length": 0.5,   # SUMO 1스텝 = 0.5초. RL의 1 timestep과 동일.
                          # 작게 하면(0.1) 제어가 정밀해지지만 에피소드가 길어지고,
                          # 크게 하면(1.0) 학습이 빨라지지만 제어가 거칠어진다.
    "max_steps": 1000,    # 에피소드 최대 스텝 수. 1000 * 0.5초 = 500초.
                          # 도로 12km를 평균 24 m/s로 달리면 약 1000스텝.
                          # 이 시간 안에 완주 못하면 truncation(시간 초과) 처리.
    "warmup_steps": 4,    # ego 투입 전 프리필 차량들이 자리잡는 정착 스텝.
                          # (도로 전체를 채우는 일은 road_config의 prefill이
                          #  담당하므로 길게 흘릴 필요가 없다)

    # SUMO GUI 공통 설정 — GUI 확대는 여기 하나만 바꾸면 된다.
    # view_road.py, train/test GUI, 데이터 수집 GUI와 생성되는 highway.gui.xml까지
    # 모두 이 값을 사용한다. 숫자가 클수록 더 가까이 확대된다.
    "gui_zoom": 4000.0,   # ego 추적 시 확대 배율(%). SUMO zoom은
                          # "네트워크 전체=100%" 기준이라 도로가 길수록
                          # 큰 값이 필요. 12km 기준 4000% ≈ 시야 300m.
                          # 도로 길이를 바꾸면 이 값도 비례해 조정할 것.
    "gui_delay": 100.0,
    "gui_view_width": 200.0,  # GUI 대기 화면에서 보여줄 도로 폭(m).
                              # 도로 시작 구간이 이 폭만큼 확대되어 보인다.
                              # (▶ 재생 후에는 gui_zoom의 ego 추적으로 전환)
    "gui_track_ego": True,
}

# ──────────────────────────────────────────────────────────────
# 2) 관측 (Observation, 상태 S) — 31차원, 범위 [-1, 1]
#
# "내 차선 + 양옆 2차선씩" 총 5개 차선의 국소 교통 상황을 본다.
# (3차선 도로에서 맨 왼쪽에 있어도 오프셋 -2로 맨 오른쪽 차선까지 보임 —
#  존재하지 않는 오프셋은 연결성 -1 / 밀도 1(꽉 참)으로 인코딩된다)
# 도로 구조(차선 수, 차선 감소 위치 등)에 하드코딩 없이 SUMO 네트워크를
# 실시간 조회하므로, 도로를 바꿔도 관측 코드는 그대로 동작한다.
#
# 레이아웃 (W = visibility, vmax = 제한속도):
#   [0]      내 절대속도 / vmax                                  (0 ~ 1)
#
#   차선별 블록 × 5 (순서: 좌2, 좌1, 현재, 우1, 우2 / k = 0..4)
#   [1+4k]   선행차 상대거리 / W        (0~1,  없으면 1  = "앞이 뻥 뚫림")
#   [2+4k]   선행차 상대속도 / vmax     (-1~1, 없으면 1  = "위협 없음")
#   [3+4k]   후행차 상대거리 / W        (-1~0, 없으면 -1 = "뒤가 뻥 뚫림")
#   [4+4k]   후행차 상대속도 / vmax     (-1~1, 없으면 -1)
#     · 현재 차선 블록은 k=2 → [9..12] (선행거리 = obs[9])
#     · ±2 차선은 SUMO getNeighbors 미지원이라 차선 직접 스캔으로 감지
#     · 상대거리 부호: 선행 +, 후행 -  /  상대속도 = (상대차 속도 - 내 속도)
#     · 상대량이므로 내 절대속도[0]와 조합하면 절대값 복원 가능
#
#   차선 연결성(끊김 정도) × 5 (같은 순서)
#   [21..25]:
#        -1 : 그 차선이 아예 없음 (내가 맨 왼쪽이면 왼쪽 차선 = -1)
#         1 : W 이내에서 계속 이어짐
#      0~1  : 그 거리 비율(거리/W)만큼 가면 차선이 끝남
#             (다음 edge에 연결이 없는 차선 → 합류/차선감소 예고 신호)
#
#   차선별 전방 차량 밀도 × 5 (같은 순서)
#   [26..30]:
#      0~1  : (W 이내 전방 차량 수) / (최대 수용 대수)
#         0 : 텅 빈 차선  ↔  1 : 꽉 찬 차선
#         1 : 차선이 없는 경우도 1 = "꽉 찬 것" 취급 → 자연스럽게 회피 학습
#      · 곧 끊기는 차선은 남은 거리 기준으로 세므로 같은 대수여도 밀도가
#        높게 나온다 ("끊기는 차선에 차가 몰림" 신호)
# ──────────────────────────────────────────────────────────────
OBSERVATION = {
    "visibility": 50.0,          # 관측 가능 거리 W (m). 앞뒤 차량 감지와
                                 # 상대거리/연결성/밀도 정규화의 기준.
    "density_veh_length": 7.5,   # 밀도 계산 시 차량 1대의 점유 길이 (m)
                                 # = 차체(~5m) + 최소 안전간격(~2.5m).
                                 # 최대 수용 대수 = W / 이 값
}

# ──────────────────────────────────────────────────────────────
# 3) 행동 (Action, A) — [종방향 가감속, 차선 변경] 2차원
#
# policy가 내는 원시 행동:
#   action[0] = accel ∈ [-1, 1]
#       +1: 최대 가속, 0: 속도 유지, -1: 최대 감속
#
#   action[1] = lane_raw ∈ [-1, 1]
#       환경에서 가장 가까운 {-1, 0, +1}로 양자화해서 실제 차선 명령으로 사용.
#       +1 = 왼쪽 한 차선, 0 = 현재 차선 유지, -1 = 오른쪽 한 차선
#
# PPO는 기존 Gaussian 연속정책을 그대로 유지하고 lane_raw만 환경에서 3값으로
# 양자화한다. 따라서 기존 PPO 구현을 크게 바꾸지 않고 차선변경까지 함께 학습한다.
# 데이터 수집 시에는 raw 행동과 실제 적용된 {-1,0,+1} 명령을 둘 다 저장한다.
# ──────────────────────────────────────────────────────────────
ACTION = {
    # ──────────────────────────────────────────────────
    # 차선변경 안전 게이트 (측면충돌 방지)
    #
    # 변경 명령이 와도 목표 차선의 앞뒤 간격이 아래 조건을 만족하지
    # 않으면 실행하지 않는다 (→ invalid_action_penalty 부과):
    #   앞: gap > min_front_gap + front_tau × 내 속도
    #   뒤: gap > min_rear_gap  + rear_tau  × 후행차 속도
    # 속도 비례 항(tau)은 "빠르게 접근 중인 5m"와 "정지 상태의 5m"의
    # 위험도 차이를 반영한 시간여유 기반 판정이다.
    #
    # 이 게이트가 없으면(안전장치 OFF 환경에서) 무작위 탐험 단계의
    # 차선변경 시도 대부분이 측면충돌 즉사로 이어져, 에이전트가
    # "차선변경 = 죽음"만 학습하고 변경 자체를 포기하는 지역최적에
    # 빠진다. 게이트는 탐험을 살려두되, 종방향(추돌) 위험은 그대로
    # 남겨서 감속/차간유지 학습 신호는 유지한다.
    # ──────────────────────────────────────────────────
    "lane_change_safety": {
        "enabled": True,
        # ↓ 공격적 세팅: 최소한의 물리적 여유만 남기고 바짝 파고들기 허용.
        #   (기존 5.0/0.3/0.5/1.0 → 충돌이 다시 늘면 그 값으로 되돌릴 것)
        "min_front_gap": 3.0,   # m
        "min_rear_gap": 3.0,    # m
        "front_tau": 0.15,      # s (내 속도 기준)
        "rear_tau": 0.3,        # s (후행차 속도 기준)
        "approach_horizon": 0.6,  # s. 접근 여유 판정 시간 — "이 시간 안에
                                  # 상대와 만나면 위험". 짧을수록 공격적.
        "spawn_protect": 60.0,  # m. 도로 시작 이 구간 안에서는 변경 금지.
                                # flow가 입구에서 새 차를 만드는데 "생성 직전"
                                # 차량은 관측 불가라 원천 사각지대이기 때문.
    },

    "dim": 2,
    "accel_index": 0,
    "lane_change_index": 1,
    "lane_change_values": (-1, 0, 1),
    "lane_change_threshold": 0.5,   # raw <= -0.5→-1, >=+0.5→+1, 그 사이→0
    "lane_change_duration": 1.0,    # SUMO에 차선 변경 명령을 유지하는 시간(초)
}

# ──────────────────────────────────────────────────────────────
# 4) 보상 (Reward, R)
#
# 매 스텝 보상 = speed_weight * (현재속도 / vmax)          ← 빠를수록 +
#              - close_gap_penalty (간격 < threshold 일 때) ← 위험운전 벌점
# 종료 보상   = -collision_penalty (충돌)  또는  +arrival_bonus (완주)
#
# 설계 의도:
#   속도 보상만 있으면 "무조건 밟는" 정책이 나와 충돌한다.
#   충돌 벌점만 크면 "겁먹고 서 있는" 정책이 나온다.
#   이 둘 사이 균형을 잡는 것이 보상 설계(reward shaping)의 핵심이며,
#   아래 숫자들을 바꿔가며 정책이 어떻게 달라지는지 관찰해보길 권장.
# ──────────────────────────────────────────────────────────────
REWARD = {
    "speed_weight": 0.1,         # 속도 보상 가중치. 한 스텝 최대 +0.1
    "close_gap_threshold": 6.0, # 앞차와 이 거리(m) 미만으로 붙으면 (좁게 따라붙기 허용:
                                 #  10→6m 완화. 추월 직전 대기 위치를 잡기 쉬워짐)
    "close_gap_penalty": 0.1,    #   → 스텝당 이만큼 감점
    "collision_penalty": 5.0,    # 충돌 시 -5 를 받고 에피소드 즉시 종료
    "arrival_bonus": 2.0,        # 도로 끝까지 완주하면 +2 받고 종료

    # ---- 막힘(blocked) 페널티: 추월 학습의 핵심 신호 ----
    # "느린 앞차에 막혀 있는 상태"에 매 스텝 감점을 준다.
    #   조건: 같은 차선 앞차가 blocked_gap 이내  AND  내 속도가
    #         제한속도 × blocked_speed_frac 미만 (= 막혀서 느린 중)
    # 왜 필요한가: 속도 보상만으로는 "변경의 이득"이 미래에 분산되어
    #   도착하는 데다, 막힘 상태 자체가 드물어(스텝의 ~5%) 학습 신호가
    #   너무 희박하다 (실측: 12업데이트에도 막힘 상태와 일반 상태의
    #   변경확률이 분화되지 않음). 이 페널티는 "유지 = 매 스텝 감점,
    #   변경으로 탈출 = 감점 즉시 중단"이라는 즉각적 차등을 만들어
    #   정확히 그 상태에서 차선변경을 배우게 한다.
    "blocked_penalty": 0.05,     # 막힘 상태 스텝당 감점 (0이면 비활성)
    "blocked_gap": 20.0,         # 앞차가 이 거리(m) 이내면 "막힘" 후보
    "blocked_speed_frac": 0.7,   # 그리고 내 속도 < vmax×이 값일 때만
                                 # (앞이 가까워도 빠르게 흐르면 막힘 아님)

    # ---- 차선변경 관련 (원본 Flow 코드의 lc_penalty / rl_action_penalty 대응) ----
    # ★ 커리큘럼: 두 페널티 모두 초기 학습에서는 0으로 둔다.
    #   실측(run_130630): 페널티 0.05 상태에서 p_lane_change가
    #   0.37→0.11로 단조 붕괴 — 시도의 상당수가 게이트에 막혀 -0.05,
    #   실행돼도 즉시 -0.05인 반면 추월 이득은 지연·분산되어 오므로
    #   "변경 = 손해"만 학습됨. 페널티 없이 추월을 먼저 배우게 하고,
    #   학습 후 지그재그가 과하면 0.02~0.05로 재도입할 것.
    "lane_change_penalty": 0.0,   # 차선변경이 "실행될 때마다" 감점.
                                   #   목적: 이득 없는 지그재그(웨빙) 억제.
                                   #   속도 보상(스텝당 최대 0.1)의 절반 수준이라,
                                   #   "변경해서 더 빨라질 때만 변경"하도록 유도.
                                   #   0으로 두면 자유롭게 바꾸는 정책이 나온다.
    "invalid_action_penalty": 0.0,  # 실행 불가능한 차선변경을 "명령"하면 감점.
                                     #   (맨 왼쪽에서 또 왼쪽, 교차로 내부 등)
                                     #   목적: 의미 없는 행동 출력 자체를 줄여
                                     #   행동 분포를 깔끔하게 만드는 정칙화.
}
# 보상 스케일에 대한 메모 (수업에서 다뤄볼 만한 지점):
#   처음엔 speed_weight=1.0, collision=-10, arrival=+5 였는데,
#   400스텝 동안 스텝당 +1이 쌓이면 에피소드 리턴이 ~100까지 커진다.
#   그러면 (a) critic이 큰 값을 맞추느라 value_loss가 요동치고,
#          (b) "빨리 달리다 충돌(-10)" 이 "천천히 완주" 보다 이득이 되어
#              충돌 회피를 배울 유인이 약해진다.
#   그래서 속도 보상을 1/10로 줄여 리턴을 ~10 규모로 낮췄다.
#   → 보상의 절대값이 아니라 "항 사이의 상대 비율"이 정책을 결정한다는
#     점을 확인해보는 실험을 해보길 권장.
